--- LAYER: API verification (GraphQL automated) ---
[AUTH role=PUBLIC]
[GQL-OP sortings_custom]
  query SortingsCustom($storeId: String! $currencyCode: String $cultureName: String) {
    products(storeId: $storeId currencyCode: $currencyCode cultureName: $cultureName first: 1 withFacets: true) {
      sortings { id name isDefault selected }
    }
